import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"InternVLA-M1: A Spatially Guided Vision-Language-Action Framework for Generalist Robot Policy","description":"","frontmatter":{"title":"InternVLA-M1: A Spatially Guided Vision-Language-Action Framework for Generalist Robot Policy","arxiv":"2510.13778","date":"2025-10-15","authors":"Xinyi Chen, Yilun Chen, Yanwei Fu, Ning Gao, Jiaya Jia, Weiyang Jin, Hao Li, Yao Mu, Jiangmiao Pang, et al.","categories":"cs.RO, cs.AI, cs.CV","topics":"空间接地, 双系统 VLA, 合成数据协同训练","outline":[2,2]},"headers":[],"relativePath":"papers/2510.13778.md","filePath":"papers/2510.13778.md","lastUpdated":null}'),l={name:"papers/2510.13778.md"};function e(i,s,r,m,o,c){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="internvla-m1-a-spatially-guided-vision-language-action-framework-for-generalist-robot-policy" tabindex="-1">InternVLA-M1: A Spatially Guided Vision-Language-Action Framework for Generalist Robot Policy <a class="header-anchor" href="#internvla-m1-a-spatially-guided-vision-language-action-framework-for-generalist-robot-policy" aria-label="Permalink to &quot;InternVLA-M1: A Spatially Guided Vision-Language-Action Framework for Generalist Robot Policy&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2510.13778" target="_blank" rel="noreferrer">2510.13778</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-10-15</td></tr><tr><td><strong>作者</strong></td><td>Xinyi Chen, Yilun Chen, Yanwei Fu, Ning Gao, Jiaya Jia, Weiyang Jin, Hao Li, Yao Mu, Jiangmiao Pang, et al.（Intern Robotics / 上海人工智能实验室，署名按姓氏字母序）</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.AI, cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>先用 230 万条点/框/轨迹数据把 Qwen2.5-VL-3B 训成&quot;会指位置&quot;的空间先验器，再在动作后训练里用一句空间提示词把这份先验以隐式 latent plan 的形式喂给 DiT 动作专家，并与接地数据协同训练防止遗忘。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>指令跟随机器人有一个反复出现的失败模式：模型能把动作做得很流畅，却做在了错的物体上。这背后是一个结构性错配——遥操作数据教的是&quot;怎么动&quot;，而语言指令要求的是先确定&quot;在哪儿动&quot;。前者的数据规模最多几千小时，后者需要的空间接地能力在互联网图文语料里其实很丰富，但那份能力在 VLA 微调过程中会被迅速冲掉。</p><p>作者的立论是：<strong>空间接地（spatial grounding）是指令与动作之间那个缺失的中间量</strong>，而且它是本体无关的。&quot;把红色马克杯放进左边的篮子&quot;这句话里，&quot;红色马克杯在图像的哪个像素&quot;这件事对 Franka、WidowX、G1 都是同一个答案；只有从那个像素出发怎么规划关节角才是本体相关的。把这两件事分开，前者可以用海量非机器人数据训练并跨平台复用，后者才需要昂贵的真机演示。</p><p>这个划分的价值在于它改变了数据经济学：如果空间先验能从 230 万条网页/仿真/机器人接地数据里获得，那么真机数据就只需要负责最后一段&quot;怎么动&quot;。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>分层机器人系统</strong>（VoxPoser、CoPa、RoboPoint 一系）显式地把空间先验编码出来，用检测器/SAM/DINO 给出坐标，再交给规则化的规划器。它们的空间接地是可靠的，但符号化的任务分解与手工规划启发式使系统难以自动扩展到复杂任务，也切断了端到端学习。</p><p><strong>端到端 VLA</strong>（OpenVLA、RT-2、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、GR00T）走另一极端，直接从演示学控制。作者的批评很准确：这类模型倾向于<strong>过拟合细粒度运动模式而欠泛化到高层语言</strong>，尤其是涉及绝对或相对位置的指令。原因也不难理解——行为克隆的损失不会因为你把&quot;左边&quot;理解错而额外惩罚你，只要动作序列在训练分布里出现过。</p><p><strong>显式中间表示路线</strong>（ECoT、RT-H、MolmoAct、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、OneTwoVLA）在动作前生成文本计划或可视化轨迹。它们确实注入了推理，但推理内容要在推理期被<strong>逐 token 生成</strong>，带来实打实的延迟。本文的差异化定位就在这里：把接地能力放进 latent plan，不在推理期生成任何显式中间输出。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一步是承认一个数据事实：机器人演示的规模天花板远低于图文语料，因此凡是能从图文语料里学的能力都不该用演示去学。指点、框选、画轨迹这三类任务恰好都能从 RefCOCO、Pixmo-Points、RoboPoint、RefSpatial 这类现成资源里拿到，而且它们的输出（像素坐标）天然本体无关。</p><p>第二步是问：这份能力怎么传给动作头？最直白的是让 VLM 显式输出坐标再喂给控制器——但那就退回分层系统，且要付出解码延迟。替代方案是让动作头直接读 VLM 的<strong>隐状态</strong>。可是隐状态里同时混着语义、空间、以及大量与任务无关的内容，怎么让动作头读到该读的那部分？</p><p>第三步给出了一个很轻的答案：既然模型已经被训练成&quot;看到某类提示就去做空间定位&quot;，那就在指令后面<strong>追加一句空间提示词</strong>（例如&quot;Figure out how to execute it, then locate the key object needed.&quot;），即使模型不真的把答案说出来，这句提示也会激活相应的注意力模式，使隐状态里的空间成分被放大。这是 prompt engineering 在表示层面的用法。</p><p>第四步是防遗忘：只在演示数据上做后训练会让接地能力迅速退化，所以训练要在轨迹数据与接地数据之间交替；同时为了防止动作梯度污染 VLM 的语义能力，在 querying transformer 处加一个 0.5 的梯度衰减因子。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>&quot;在哪儿动&quot;是本体无关的、可以用海量非机器人数据学；&quot;怎么动&quot;是本体相关的、只能用演示学。把两者显式拆开，再用一句空间提示词把前者激活成隐式 latent plan 交给后者，就既避免了分层系统的解码延迟，又避免了端到端 VLA 把语言理解退化成运动模式记忆。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以&quot;把桌上的胡萝卜放到盘子里&quot;为例。</p><p><strong>架构。</strong> System 2 是 Qwen2.5-VL-3B-Instruct，负责空间先验；System 1 是一个 86M 的 diffusion policy 动作专家，配一个**独立的 DINOv2 视觉编码器（21M）**与轻量状态编码器（0.4M）。总参数约 4.1B，单张 RTX 4090 约 12GB 显存，VLM 侧配 FlashAttention 约 10 FPS。两者之间是一个 8.7MB 的 querying transformer：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 层 cross-attention，固定数量的可学习 query token 去 attend VLM 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 个中间层，把变长输入压成定长条件。</p><p><strong>阶段一：空间接地预训练。</strong> 只训 VLM，超过 300 万条多模态样本，其中 230 万条是空间推理数据，分四类：General QA 约 637K（LLaVA-OneVision、InternVL3）、Box QA 约 879K（RefCOCO、ASv2、COCO-ReM、RoboRefIt、自建 InternData-M1）、Trajectory QA 约 684K（A0 ManiSkill 子集、InternData-M1 waypoint、MolmoAct）、Point QA 约 832K（Pixmo-Points、RoboPoint、RefSpatial）。所有坐标转为绝对坐标，输出格式为 JSON/XML。</p><p><strong>阶段二：空间引导动作后训练。</strong> VLM 与动作专家联合优化。轨迹数据上两侧都用 L2 噪声预测损失；接地数据上只更新 VLM 走 next-token prediction。指令前会拼一句空间提示词，模型<strong>不显式输出</strong>对该提示的回答。梯度从动作专家回传到 VLM 时乘 0.5。</p><p><strong>数据引擎。</strong> 基于 GenManip + Isaac Sim 的全自动流水线：场景图求解器随机布局，基于网格算候选抓取，每条候选轨迹在物理引擎里跑一遍做闭环验证，再由场景图验证器判断目标是否达成，只保留双双通过的。规划与渲染<strong>完全解耦</strong>——规划器只记结构化数据，渲染器事后在随机光照/材质/视角下回放，顺带产出框与 2D 末端轨迹作为接地监督。相机用 ArUco 标定使内外参与真机一致。资产库含 14K 标注物体、211 张桌子、1.6K 纹理、87 个 dome light。由此产出 244K 条闭环 pick-and-place 样本。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文没有给出新的形式化目标，训练目标是两项标准损失的求和（轨迹侧的扩散 L2 与接地侧的交叉熵），文中未给权重。真正值得形式化讨论的是<strong>梯度衰减因子</strong>这一处设计。</p><p>设 VLM 参数为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，动作专家为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">a</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，querying transformer 输出的条件为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">Q</span><span class="mopen">(</span><span class="mord mathnormal">h</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">))</span></span></span></span>。加入衰减因子 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.5</span></span></span></span> 后，动作损失对 VLM 的梯度变为</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9334em;vertical-align:-0.2501em;"></span><span class="mord"><span class="mord">∇</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1645em;"><span style="top:-2.357em;margin-left:-0.0278em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2501em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">act</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">←</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.2074em;vertical-align:-0.836em;"></span><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3714em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord" style="margin-right:0.0556em;">∂</span><span class="mord mathnormal">c</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord" style="margin-right:0.0556em;">∂</span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">act</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3714em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord" style="margin-right:0.0556em;">∂</span><span class="mord mathnormal">h</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord" style="margin-right:0.0556em;">∂</span><span class="mord mathnormal">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3714em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord" style="margin-right:0.0556em;">∂</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord" style="margin-right:0.0556em;">∂</span><span class="mord mathnormal">h</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.836em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mpunct">,</span></span></span></span></span></p><p>而接地损失的梯度不缩放。因此有效目标等价于优化 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">act</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ground</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> <strong>在 VLM 上的分量</strong>，同时保持 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">act</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 在动作专家上的完整梯度。换句话说这不是一个统一目标的优化，而是<strong>两个不同目标分别作用在两组参数上</strong>——VLM 看到的目标里接地权重被相对抬高了 2 倍。这一点论文没有点破，但它解释了为什么表 3 里 InternVLA-M1 的多模态理解与接地分数都高于朴素协同训练。</p><p>作者另外报告了 Projection-space Similarity（基于 SVD 的梯度子空间相似度）：朴素协同训练下接地目标与动作目标的 PSS 仅 0.25，加入空间提示词后升到 0.42。这是一个诚实且有信息量的量——它说明两个目标的梯度子空间原本近乎正交，而空间提示词把它们拉近了。但要注意 PSS 升高本身既可以解释为&quot;两个任务变得更协同&quot;，也可以解释为&quot;动作目标的梯度被 VLM 的接地模式主导了&quot;，论文未做区分。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：空间引导相对同架构基线值多少？</strong> 对照组 Vanilla VLA 是同一个 Qwen2.5-VL-3B + DiT 动作头，但不做空间接地预训练、不加空间提示、不做协同训练。SimplerEnv Google Robot Visual Matching 66.1→80.7（+14.6），Variant Aggregation 63.5→76.0（+12.5，正文写 12.4），WidowX 54.7→71.7（+17.0），LIBERO 91.6→95.9（+4.3）。这些数字很大，但对照组一次性移除了三个组件，因此是一个&quot;整套配方&quot;的效应而非任一组件的效应。</p><p><strong>问题二：相对既有 SOTA 呢？</strong> 这里需要非常小心地读表。Google Robot VM 的 Avg 列并非在同一批任务上计算：CogACT、Vanilla VLA、InternVLA-M1 的均值是四项任务（含最难的 &quot;Open Top Drawer and Place Apple&quot;）的算术平均，可逐位验算；而 SpatialVLA、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>-FAST 的第四项为&quot;-&quot;，其 Avg 只覆盖三项。因此&quot;比 SpatialVLA 的 75.1 高 5.6&quot;这一比较<strong>不是同口径</strong>。正文写&quot;5.9% gain in Google Robot Visual Matching&quot;，而按表算是 80.7−75.1=5.6，两者对不上。WidowX 表里还有一处更明确的错误：<strong><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>-FAST 一行四项是 29.1/21.9/10.8/66.6，算术平均 32.1，表中 Avg 却记 48.3</strong>（其余每一行的 Avg 都能逐位复原）。</p><p>逐项看也并非全胜：Variant Aggregation 的 Pick Coke Can 一项 InternVLA-M1 <strong>86.1 低于 Vanilla VLA 的 92.3（Δ=−6.2）</strong>，也低于 SpatialVLA 的 88.0；WidowX 的 Stack Green Block 一项 31.3 远低于 GR00T N1.5 的 57.0。LIBERO 上 95.9 领先，但 Goal 一列 93.8 低于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的 95.8 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>-KI 的 95.6。</p><p><strong>问题三：协同训练是否保住了理解与接地？</strong> 表 3 显示 InternVLA-M1 相对朴素协同训练在 MME（1106→1411）、MMVet、TextVQA、POPE、RefCOCO-g（47.1→71.2）、Where2place、A0-maniskill 上全面更好。两处需注意：<strong>Vanilla VLA 那一行的理解与接地全部为&quot;-&quot;</strong>，因此&quot;相对不做接地的 VLA 保住了多少能力&quot;这一最直接的问题没有数据；COCO Caption 的 ROUGE 从 15.1 降到 13.4（BLEU 从 10.4 升到 13.0），并非全项更好。</p><p><strong>问题四：大规模指令跟随。</strong> 自建 200 个 pick-and-place 任务、3K+ 物体，四种设定（分布内/未见物体/新背景/未见指令），相对 GR00T N1.5 平均 +6.2%。结果只在图 7，无数值表。</p><p><strong>问题五：真机。</strong> Franka + Robotiq 2F-85，双 D435；23 个见过的物体、5 个容器，6 小时遥操作演示；每模型 300 次 rollout，每个设定至少 50 次。摘要报 +7.3%（杂乱场景 pick-and-place）与协同训练后未见物体/新配置 +20.6%，长时程推理场景&quot;超过既有工作 10% 以上&quot;。<strong>这三个数只出现在摘要与引言，§4.2.2 的结果分析全篇无数字</strong>，图 10/12 无数值标注，本文不复述任何未在正文出现的分项数据。</p><p><strong>表 5（规划器对比）</strong> Ours-3B 在五类任务上 90/91/91/93/92，高于 GPT-5 的 75/67/62/79/82 与 Gemini-2.5 Pro。但 Ours-3B 是在这五个任务上用 22 小时、约每任务 500 条带子任务标注的演示后训练过的，而 GPT-5 等是零样本——这不是一个可比的对照，论文的表述&quot;despite GPT-5&#39;s strong reasoning capability&quot;容易被读成一般性结论。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版。</strong> InternVLA-M1 主张空间接地是指令与动作之间的本体无关中间量，因此可以用 230 万条非机器人接地数据先学、再迁到控制。它用 Qwen2.5-VL-3B 做 System 2、86M diffusion policy 做 System 1，靠一个 8.7MB 的 querying transformer 与一句&quot;空间提示词&quot;把先验以隐式 latent plan 传下去，推理期不生成任何显式中间输出。为防遗忘与梯度冲突，训练在轨迹数据与接地数据间交替，并把动作回传到 VLM 的梯度乘 0.5。相对同架构无空间引导的对照，SimplerEnv Google Robot +14.6、WidowX +17.0、LIBERO +4.3，同时多模态理解与接地分数也高于朴素协同训练。但对照组一次性移除三个组件，逐组件贡献未被分离，且主表的 Avg 列在不同方法间覆盖的任务数并不一致。</p><p><strong>3 句话版。</strong> 把&quot;在哪儿动&quot;从演示数据里剥出来，用便宜得多的接地语料学，再用提示词把它激活成隐式条件。这套配方整体有效且工程完整度很高。它的证据结构偏&quot;系统级&quot;，单个设计的因果贡献基本没有被隔离。</p><p><strong>1 句话版。</strong> 空间接地作为本体无关先验是个好划分，但本文证明的是整套配方有效，不是空间引导有效。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最致命的一条：<strong>动作专家读到的空间信息，主要来自 VLM 的 latent plan。</strong></p><p>之所以说它最致命，是因为整篇论文的框架名（&quot;spatially guided&quot;）与因果叙事都建立在这条链路上；若这条链路是次要的，那么 +14.6 就必须由别的东西解释。而论文自己的架构描述给出了一条竞争通路：<strong>动作专家配备了自己的 DINOv2 视觉编码器（21M），直接看原始图像</strong>。也就是说 System 1 有两路输入——一路是经 querying transformer 压缩的 VLM latent，一路是它自己的视觉特征。空间信息完全可以从后者获得，而 VLM 侧的接地预训练可能主要起到&quot;给动作专家提供一个更稳定的初始化/正则&quot;的作用。</p><p>论文提供的相关证据有三条，但都不能定这个案。图 5 的消融显示&quot;去掉空间数据与空间提示会导致接地能力快速退化、操作收敛变慢&quot;——这证明空间引导影响训练动力学，不证明它在推理期承载空间信息。PSS 从 0.25 升到 0.42 说明梯度子空间对齐改善，同样是训练期的量。表 3 说明 VLM 的接地分数更高，但没有把 VLM 的接地分数与动作成功率做逐实例关联。</p><p>缺失的关键证据只有一条，而且做起来很便宜：<strong>在推理期把 querying transformer 的输出置零/替换成随机向量/替换成另一条指令的 latent，看成功率掉多少</strong>。若掉得不多，说明 latent plan 在部署时是惰性的；若掉得很多，本文的因果叙事立刻被坐实。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，代码与模型均已开源。</p><ul><li><strong>设定</strong>：直接用官方 InternVLA-M1 权重，在 SimplerEnv WidowX 与 Google Robot VM 上评测，不做任何训练。</li><li><strong>四个推理期干预</strong>：(1) 原样；(2) querying transformer 输出置零；(3) 输出替换成同一 batch 里另一条<strong>无关指令</strong>的 latent（保留统计量、破坏语义）；(4) 保留 latent 但把动作专家自己的 DINOv2 输入替换成高斯噪声。</li><li><strong>测量</strong>：四项任务的成功率，以及每步动作与原样推理的 L2 偏差。</li><li><strong>判据</strong>：若 (2)/(3) 相对 (1) 的下降远小于 (4)，则动作专家主要依赖自己的视觉通路，&quot;空间引导&quot;的作用应重新定位为训练期正则；若 (3) 下降显著大于 (2)，说明 latent 承载的是<strong>指令特定</strong>的空间信息，本文叙事成立；若 (2) 与 (3) 都几乎不掉，则应把 +14.6 的功劳重新归因到接地预训练对 VLM 视觉塔的改良与协同训练的正则效应上。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>反对者最有力的攻击是指出：<strong>表 1/表 2 的&quot;新 SOTA&quot;结论建立在不可比的 Avg 列上，而唯一可比的对照（Vanilla VLA）同时改变了三个变量。</strong></p><p>第一部分的证据是硬的。Google Robot VM 表里，CogACT 的 74.8 可由 (91.3+85.0+71.8+50.9)/4 精确复原、InternVLA-M1 的 80.7 可由 (95.3+90.0+75.5+62.0)/4 复原，而 SpatialVLA 的 75.1 与 (86.0+77.9+57.4)/3=73.8 都对不上，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的 58.8 恰等于三项均值 58.77——这说明这些行的 Avg 覆盖三项任务且不含最难的抽屉+苹果任务。用四项均值去和三项均值比&quot;高 5.6&quot;，方向上是有利于本方法的（因为第四项恰是最难的一项，纳入它会拉低分母中的其它模型）。WidowX 表里 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>-FAST 的 48.3 与其四项均值 32.1 相差 16 个点，是一处必然的抄录错误。</p><p>第二部分的替代解释是：Vanilla VLA 与 InternVLA-M1 之间同时相差 (i) VLM 是否经过 230 万条接地数据预训练、(ii) 是否加空间提示词、(iii) 是否在后训练期与接地数据协同。其中 (i) 单独就足以解释很大一部分——接地预训练本质上是在给 Qwen2.5-VL 的视觉塔做大规模高质量继续训练，即便完全不用 latent plan，一个更好的视觉塔也会让下游控制更好。论文缺的正是这个 arm：<strong>&quot;用接地预训练过的 VLM，但不加空间提示、不做协同训练&quot;</strong>。</p><p>一个可预测的失败场景：把评测换成需要<strong>相对空间关系</strong>且干扰物与目标外观相近的设定（例如&quot;拿起靠近碗的那个胡萝卜&quot;，桌上有两根一样的胡萝卜）。此时动作专家自己的 DINOv2 通路无法从外观区分目标，必须依赖 latent plan 里的位置信息。按本文叙事这类任务应当受益最大；若增益反而消失，说明 latent plan 传的更多是&quot;物体类别&quot;而非&quot;空间位置&quot;。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动局限。</strong> 本文用一句自然语言提示词去&quot;激活&quot;隐状态里的空间成分，这是一个纯经验的接口——没人知道那句话激活了什么、激活了多少，也没法保证换个措辞不会失效。更根本地，latent plan 是不可读的，因此当机器人抓错物体时，无法判断是接地错了还是控制错了。这在调试与安全审计上都是硬伤，而它正是&quot;隐式优于显式&quot;这一取舍的代价。</p><p><strong>(b) 可借鉴的相邻工具。</strong> 可解释性研究里的<strong>稀疏自编码器 / 字典学习</strong>（用于在 LLM 隐状态里找出单义方向）提供了一条把 latent plan 变成可读且可干预对象的路径：在 querying transformer 的输出上训一个过完备稀疏字典，把定长条件分解成若干稀疏激活的原子，再用已有的框/点标注去<strong>给原子命名</strong>（哪些原子在&quot;目标在图像左侧&quot;时激活）。这样 latent plan 就获得了一个可读的坐标系，而不需要在推理期解码任何文本。</p><p><strong>(c) 第一个实验长什么样。</strong> 在 200 任务的仿真基准上收集 InternVLA-M1 的条件向量与对应的真值目标框，训一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">8</span><span class="mord">×</span></span></span></span> 过完备的稀疏自编码器（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord">ℓ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 稀疏约束），然后做三件事：(i) 用线性探针检验单个原子能否预测目标物体的图像坐标，报可解释方差；(ii) 在推理期<strong>定向干预</strong>——把&quot;目标在左&quot;的原子置换成&quot;目标在右&quot;的原子，看机器人是否真的转去抓右边的物体（这是因果性的直接检验，也顺带回答 §9 的问题）；(iii) 统计失败 rollout 里&quot;接地原子错误&quot;与&quot;接地正确但动作错误&quot;的比例，给出第一份 VLA 失败模式的可归因分解。若干预能稳定改变抓取目标，那么这套字典就可以直接当作一个安全层——在执行前检查接地原子是否与指令一致，不一致就拒动，而这在当前的隐式设计下是做不到的。</p>',59)])])}const u=a(l,[["render",e]]);export{h as __pageData,u as default};
